"""
SLA por empresa (spec 026).

A prioridade saiu das telas (spec 025) e toda ocorrência nova é "media":
das regras sem empresa, a de prioridade "media" vira a de prioridade
"qualquer" (o padrão), e as de "alta"/"baixa", que nenhuma ocorrência nova
alcança, são apagadas. O prazo das novas não muda. Não há volta dos dados.
"""

import django.db.models.deletion
from django.db import migrations, models


def prioridade_vira_padrao(apps, schema_editor):
    SlaRegra = apps.get_model("ocorrencias", "SlaRegra")
    SlaRegra.objects.filter(prioridade__in=["alta", "baixa"]).delete()
    for regra in SlaRegra.objects.filter(prioridade="media"):
        ja_existe = SlaRegra.objects.filter(
            empresa_id=regra.empresa_id, categoria=regra.categoria, prioridade__isnull=True
        ).exists()
        if ja_existe:  # uma regra explícita sem prioridade já valia antes: fica ela
            regra.delete()
        else:
            regra.prioridade = None
            regra.save(update_fields=["prioridade"])


